-- Release 2.0. Compatible con MariaDB 10.6+ y MySQL 8.0.16+.
-- Seleccione la base antes de importar. No contiene CREATE DATABASE para hosting compartido.
CREATE TABLE IF NOT EXISTS roles(id BIGINT PRIMARY KEY,nombre VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS usuarios(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL,usuario VARCHAR(30) NOT NULL UNIQUE,correo VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,rol_id BIGINT NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,fallos INT NOT NULL DEFAULT 0,bloqueado_hasta DATETIME NULL,creado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(rol_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS usuario_2fa(usuario_id BIGINT PRIMARY KEY,secreto_cifrado VARCHAR(255) NOT NULL,habilitado BOOLEAN NOT NULL DEFAULT FALSE,intentos INT NOT NULL DEFAULT 0,ultimo_paso BIGINT NOT NULL DEFAULT -1,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS acceso_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NULL,usuario VARCHAR(30) NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,resultado VARCHAR(30) NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS clientes(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL,telefono VARCHAR(30) NOT NULL,correo VARCHAR(254) NOT NULL DEFAULT '',creado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS empleados(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL UNIQUE,nombre VARCHAR(150) NOT NULL,especialidad VARCHAR(150) NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS categorias_servicio(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,descripcion VARCHAR(255));
CREATE TABLE IF NOT EXISTS servicios(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,precio DECIMAL(10,2) NOT NULL CHECK(precio>0),duracion_minutos INT NOT NULL CHECK(duracion_minutos BETWEEN 5 AND 480),categoria_id BIGINT NOT NULL,FOREIGN KEY(categoria_id) REFERENCES categorias_servicio(id));
CREATE TABLE IF NOT EXISTS agendas(id BIGINT AUTO_INCREMENT PRIMARY KEY,empleado_id BIGINT NOT NULL UNIQUE,UNIQUE KEY agenda_empleado(id,empleado_id),FOREIGN KEY(empleado_id) REFERENCES empleados(id));
CREATE TABLE IF NOT EXISTS horarios_trabajo(id BIGINT AUTO_INCREMENT PRIMARY KEY,empleado_id BIGINT NOT NULL,dia_semana INT NOT NULL CHECK(dia_semana BETWEEN 1 AND 7),hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,CHECK(hora_fin>hora_inicio),FOREIGN KEY(empleado_id) REFERENCES empleados(id));
CREATE TABLE IF NOT EXISTS citas(id BIGINT AUTO_INCREMENT PRIMARY KEY,cliente_id BIGINT NOT NULL,empleado_id BIGINT NOT NULL,servicio_id BIGINT NOT NULL,agenda_id BIGINT NOT NULL,fecha DATETIME NOT NULL,precio_acordado DECIMAL(10,2) NOT NULL CHECK(precio_acordado>0),duracion_acordada INT NOT NULL CHECK(duracion_acordada>0),estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN ('PENDIENTE','COMPLETADA','CANCELADA')),FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(empleado_id) REFERENCES empleados(id),FOREIGN KEY(servicio_id) REFERENCES servicios(id),FOREIGN KEY(agenda_id,empleado_id) REFERENCES agendas(id,empleado_id),INDEX ix_cita_fecha(fecha),INDEX ix_cita_empleado(empleado_id,fecha));
CREATE TABLE IF NOT EXISTS pagos(id BIGINT AUTO_INCREMENT PRIMARY KEY,cita_id BIGINT NOT NULL UNIQUE,monto DECIMAL(10,2) NOT NULL CHECK(monto>0),fecha DATETIME NOT NULL,FOREIGN KEY(cita_id) REFERENCES citas(id));
CREATE TABLE IF NOT EXISTS facturas(id BIGINT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(40) NOT NULL UNIQUE,cliente_id BIGINT NOT NULL,fecha_emision DATETIME,estado VARCHAR(12) NOT NULL DEFAULT 'BORRADOR' CHECK(estado IN ('BORRADOR','EMITIDA')),FOREIGN KEY(cliente_id) REFERENCES clientes(id));
CREATE TABLE IF NOT EXISTS detalles_factura(id BIGINT AUTO_INCREMENT PRIMARY KEY,factura_id BIGINT NOT NULL,cita_id BIGINT NOT NULL UNIQUE,descripcion_servicio VARCHAR(150) NOT NULL,importe DECIMAL(10,2) NOT NULL CHECK(importe>0),FOREIGN KEY(factura_id) REFERENCES facturas(id) ON DELETE CASCADE,FOREIGN KEY(cita_id) REFERENCES citas(id));
INSERT INTO roles(id,nombre) VALUES(1,'ADMINISTRADOR'),(2,'RECEPCIONISTA'),(3,'BARBERO') ON DUPLICATE KEY UPDATE nombre=VALUES(nombre);
